-- Aero Thunder Shot targeted completion. Frankfurt only. Preserve five existing UUIDs.
begin;
create temporary table thunder_input on commit drop as select * from jsonb_to_recordset($data$[{"id": "035abf4d-65da-5b0c-855d-9e611798c4e4", "item": "18702", "year": 2012, "jan": "4950344064496", "src": "https://www.tamiya.com/japan/products/18702/index.html", "jan_src": "https://www.1999.co.jp/10199845", "img": "https://www.tamiya.com/japan_contents/img/usr/item/1/18702/18702_1.jpg", "en": "The original Aero Thunder Shot assembly kit, released in 2012 as Mini 4WD REV Series No.2. The white body with blue and red graphics runs on a black AR chassis with large-diameter barrel tires.", "it": "La Aero Thunder Shot originale, uscita nel 2012 come secondo modello della serie Mini 4WD REV. Carrozzeria bianca con grafica blu e rossa, telaio AR nero e pneumatici barrel di grande diametro."}, {"id": "8c08137b-cfc6-5c1d-8d1b-a151d53afc01", "item": "94967", "year": 2013, "jan": "4950344949670", "src": "https://www.tqrcracing.com/shop/product_view.asp?p_id=6363", "jan_src": "https://www.1999.co.jp/10227940", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/94967/94967_1.jpg", "en": "Japan Cup 2013 commemorative kit on the AR chassis, with event-specific blue and orange graphics, orange wheels and Japan Cup tire markings.", "it": "Edizione commemorativa Japan Cup 2013 su telaio AR, con grafica blu e arancione dedicata all’evento, cerchi arancioni e pneumatici con marcature Japan Cup."}, {"id": "d0e6d2fc-3566-5004-a479-52f89253863b", "item": "94990", "year": 2013, "jan": "4950344963201", "src": "https://www.1999.co.jp/10243310", "jan_src": "https://www.1999.co.jp/10243310", "img": "https://cf.shopee.com.my/file/7f707c466ec0b1a57ea9e6699c7b96fe", "en": "Silver Metallic special assembly kit on the AR chassis, featuring a silver-plated body and matching plated wheels. Documented by HobbySearch in December 2013.", "it": "Kit speciale Silver Metallic su telaio AR, con carrozzeria argentata metallizzata e cerchi coordinati. Documentato da HobbySearch nel dicembre 2013."}, {"id": "e96a1769-9b91-55b8-84c4-697799d0b441", "item": "95273", "year": 2016, "jan": null, "src": "https://tamiya.hk/product/tamiya-95273-1-32-aero-thunder-shot-ar-asia-challenge-2016/", "jan_src": null, "img": "https://down-my.img.susercontent.com/file/th-11134207-81ztd-mislzv99jjt34f", "en": "Mini 4WD Asia Challenge 2016 commemorative kit for the Hong Kong finals. Red body, white AR chassis and white tires, with event-specific graphics and red-plated wheels.", "it": "Kit commemorativo della Mini 4WD Asia Challenge 2016, con finali a Hong Kong. Carrozzeria rossa, telaio AR e pneumatici bianchi, grafica dell’evento e cerchi metallizzati rossi."}, {"id": "324310d8-9c3d-5fa9-9d75-1202b43cfce7", "item": "95286", "year": 2017, "jan": "4950344952861", "src": "https://www.tamiya.com/japan/products/95286/index.html", "jan_src": "https://www.plazajapan.com/4950344952861/", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/95286/95286_1.jpg", "en": "Black Special kit with a smoke body, red AR chassis and red low-profile tires. Its black and red graphics continue the Thunder Shot Black Special color tradition.", "it": "Kit Black Special con carrozzeria fumé, telaio AR rosso e pneumatici ribassati rossi. La grafica nera e rossa riprende la tradizione delle Thunder Shot Black Special."}, {"id": "b95ec446-ae17-56c6-b856-0dfe863735d9", "item": "92461", "year": 2025, "jan": "4950344924615", "src": "https://hongta.co.kr/product/92461-%EC%97%90%EC%96%B4%EB%A1%9C-%EC%8D%AC%EB%8D%94%EC%83%B7-%EC%96%B4%EB%93%9C%EB%B0%B4%EC%8A%A4%EB%93%9C-%ED%8C%A9-tkc-%EC%97%90%EB%94%94%EC%85%98ar%EC%84%80%EC%8B%9C/2897/", "jan_src": "https://www.crazycathobby.it/en/tamiya-mini4wd/5068-mini-4wd-advanced-pack-aero-thunder-shot-tkc-edition-tamiya-92461-4950344924615.html", "img": "https://i0.wp.com/m4dtang.com/wp-content/uploads/2025/11/92461.jpg", "en": "Tamiya Korea Advanced Pack TKC complete assembly kit, documented in 2025. A yellow AR chassis and black-and-yellow graphics distinguish it from the standard kit; the pack includes racing upgrade components and a Hyper-Dash 3 motor.", "it": "Kit completo Advanced Pack TKC di Tamiya Korea, documentato nel 2025. Telaio AR giallo e grafica nera e gialla lo distinguono dal modello standard; la confezione include componenti da gara e motore Hyper-Dash 3."}]$data$::jsonb) as t(id uuid,item text,year integer,jan text,src text,jan_src text,img text,en text,it text);
do $$begin
 if not exists(select 1 from products where id='07cc02e9-2626-5a60-92fb-2c2ed2402d7f' and metadata->>'launch_status'='coming_soon') then raise exception 'Family baseline changed'; end if;
 if exists(select 1 from thunder_input i join product_releases r on r.item_number=i.item where r.id<>i.id) then raise exception 'Item identity conflict'; end if;
 if exists(select 1 from thunder_input i join product_releases r on r.barcode_jan=i.jan where r.id<>i.id) then raise exception 'JAN conflict'; end if;
end$$;
insert into product_releases(id,product_id,item_number,release_type,edition_type,edition_name,release_year,chassis,barcode_jan,color,country_market,discontinued,is_original,rarity,data_source,verification_status,production_status,catalog_visibility,catalog_visibility_reason)
select id,'07cc02e9-2626-5a60-92fb-2c2ed2402d7f',item,'Starter Pack','limited','Aero Thunder Shot Advanced Pack TKC Edition (AR Chassis)',year,'AR',jan,'Black / Yellow','Korea',false,false,'Uncommon','family_audit_20261102','verified','unknown','public','Verified configured complete kit with exact release photograph' from thunder_input where item='92461' on conflict(id) do nothing;
update product_releases r set barcode_jan=coalesce(i.jan,r.barcode_jan),description=i.en,description_it=i.it,updated_at=now(),notes=case when i.item='95273' then 'Asia Challenge 2016 kit. Exact box image visually verified against Tamiya Hong Kong edition specifications on 2026-11-02. JAN not independently verified.' else r.notes end from thunder_input i where r.id=i.id and r.product_id='07cc02e9-2626-5a60-92fb-2c2ed2402d7f';
insert into release_images(release_id,url,position) select id,img,0 from thunder_input i where not exists(select 1 from release_images x where x.release_id=i.id and x.url=i.img);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select id,case when item in('18702','95286') then 'official_manufacturer' else 'trusted_secondary' end,src,array['item_number','edition_name','chassis','description','description_it'],'2026-11-02','Exact complete-kit identity checked; five original UUIDs preserved. See docs/AERO_THUNDER_SHOT_FAMILY_AUDIT_2026-11-02.md. No price imported from a sold-out page.' from thunder_input i where not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.src);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select id,'trusted_secondary',jan_src,array['barcode_jan'],'2026-11-02','EAN13 checksum validated and exact product attribution checked. Identity source only.' from thunder_input i where jan is not null and not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.jan_src and 'barcode_jan'=any(x.verified_fields));
insert into release_identifiers(release_id,scheme,value,market,is_primary,verification_status,source_url,checked_at)
select id,'JAN',jan,null,true,'verified',jan_src,'2026-11-02' from thunder_input i where jan is not null and not exists(select 1 from release_identifiers x where x.release_id=i.id and x.scheme='JAN' and x.value=i.jan);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select id,'other',img,array['release_images.url'],'2026-11-02','Exact/high-confidence release photo inspected visually and Next Image rendering checked. No sibling fallback, no license claim.' from thunder_input i where not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.img);
select trackdash_enroll_release_market_scans(id) from thunder_input;
update market_scan_queue q set next_scan_at=now(),updated_at=now() where q.release_id in(select id from thunder_input) and q.source_id=(select id from price_sources where slug='ebay_active_public') and q.enabled and q.last_attempt_at is null;
-- Planned sources remain parked; no incomplete import costs enter EU valuation.
update market_scan_queue set enabled=false,next_scan_at='2099-01-01' where release_id in(select id from thunder_input) and source_id=(select id from price_sources where slug='rcjaz_public');
update market_scan_targets set enabled=false,next_scan_at='2099-01-01' where release_id in(select id from thunder_input) and source_id=(select id from price_sources where slug='rcjaz_public');
select trackdash_enqueue_market_recompute(id,'new_complete_unbuilt') from thunder_input;
commit;
select r.item_number,r.barcode_jan,q.enabled,q.last_success_at,q.next_scan_at from product_releases r join market_scan_queue q on q.release_id=r.id join price_sources s on s.id=q.source_id where r.product_id='07cc02e9-2626-5a60-92fb-2c2ed2402d7f' and s.slug='ebay_active_public' order by r.item_number;
